/* W15.7: local availability -> appointment -> reviewed documentation -> existing case/tasks. */
const MEETING_ROUTES=['/portal/appointments','/portal/student/appointments','/portal/applicant/appointments'];
const MEETING_TOPICS={study:['Studienberatung','Study guidance'],fsp:['FSP-Beratung','FSP guidance'],testas:['TestAS-Beratung','TestAS guidance'],university:['Hochschulberatung','University guidance'],arrival:['Visum & Einreise','Visa & arrival'],individual:['Individuelle Sprechstunde','Individual consultation']};
const MEETINGS={topic:'study',slotSelected:'SLOT-01',bookingSelected:null,error:null,errorRoute:'',slots:[
 {id:'SLOT-01',owner:'adminA',topic:'study',date:'2026-11-10',start:'10:00',end:'10:30',mode:'onsite',place:'',checked:false,published:false,booking:null},
 {id:'SLOT-02',owner:'adminA',topic:'study',date:'2026-11-11',start:'11:00',end:'11:30',mode:'onsite',place:'',checked:false,published:false,booking:null},
 {id:'SLOT-03',owner:'adminB',topic:'arrival',date:'2026-11-12',start:'14:00',end:'14:30',mode:'video',place:'',checked:false,published:false,booking:null}
],bookings:[]};
function meetingOwn(){return MEETING_ROUTES.includes(route())}
function meetingStaff(){return route()==='/staff/calendar'}
function meetingSlot(){return MEETINGS.slots.find(s=>s.id===MEETINGS.slotSelected)}
function meetingBooking(){return MEETINGS.bookings.find(b=>b.id===MEETINGS.bookingSelected)}
function meetingVisible(b){return !!b&&(meetingOwn()||meetingStaff()&&b.slot.owner===CASES.owner)}
function meetingStatus(b){return b.status==='booked'?t('Lokal vorgemerkt','Locally recorded'):b.status==='completed'?t('Gespräch im Muster dokumentiert','Conversation documented in sample'):t('Lokale Vormerkung storniert','Local record cancelled')}
function meetingButton(de,en,action){return `<button type="button" class="btn secondary" data-meeting-action="${action}">${t(de,en)}</button>`}
function meetingNotice(){return `<p class="learning-notice">${t('Nur lokales Terminszenario für eine fiktive Person. Keine Live-Verfügbarkeit, echte Buchung, Nachricht oder Aufzeichnung. Alle Zeiten sind Musterzeiten in Europe/Berlin; sie werden nicht gegen einen echten Kalender geprüft. Neuladen verwirft den Bestand.','Local appointment scenario for one fictional person only. No live availability, actual booking, message or recording. All times are sample times in Europe/Berlin and are not checked against a real calendar. Reloading discards the records.')}</p>`}
function meetingError(){return MEETINGS.error&&MEETINGS.errorRoute===route()?`<p id="meeting-error" class="learning-error" role="alert" tabindex="-1">${t(...MEETINGS.error)}</p>`:''}
function meetingContext(s){return `<p class="meeting-context"><b>${caseLabel(MEETING_TOPICS,s.topic)}</b><br>${esc(s.date)} · ${esc(s.start)}–${esc(s.end)} · Europe/Berlin<br>${caseOwnerLabel(s.owner)} · ${t('Vor Ort · Musterort','In person · sample place')}: ${esc(s.place)}</p>`}
function meetingEvent(b,label,text='',isPublic=true){b.history.push({at:new Date().toISOString(),actor:meetingOwn()?'learner':CASES.owner,label,text,public:isPublic})}
function meetingHistory(b,staff=false){return `<details><summary>${t('Terminverlauf','Appointment history')}</summary><ol>${b.history.filter(e=>staff||e.public).map(e=>`<li><b>${esc(e.at)} · ${e.actor==='learner'?t('Musterteilnehmer','Sample learner'):caseOwnerLabel(e.actor)}</b><p>${t(...e.label)}</p>${e.text?`<p class="learning-preserve">${esc(e.text)}</p>`:''}</li>`).join('')}</ol></details>`}
function meetingSummary(b){return b.released.length?`<section class="learning-panel"><h3>${t('Ausdrücklich freigegebene Zusammenfassung','Explicitly released summary')} · ${t('Version','Version')} ${b.released.at(-1).version}</h3><p class="learning-preserve">${esc(b.released.at(-1).summary)}</p>${b.released.length>1?`<details><summary>${t('Frühere Freigaben','Earlier releases')}</summary>${b.released.slice(0,-1).map(d=>`<article><b>${t('Version','Version')} ${d.version}</b><p class="learning-preserve">${esc(d.summary)}</p></article>`).join('')}</details>`:''}<p>${t('Keine Zulassung, Verpflichtung oder verbindliche Vereinbarung aus dieser Demo.','This demo does not grant admission or create an obligation or binding agreement.')}</p></section>`:`<p class="learning-empty">${t('Noch keine freigegebene Zusammenfassung. Interne Notizen bleiben getrennt.','No released summary yet. Internal notes remain separate.')}</p>`}
function meetingStudent(){const b=meetingBooking(),active=MEETINGS.bookings.find(x=>x.status==='booked'),slots=MEETINGS.slots.filter(s=>s.published&&!s.booking&&s.topic===MEETINGS.topic);return `<div class="dashboard learning-journey meeting-journey"><span class="eyebrow">${t('DEINE BERATUNG · MUSTER','YOUR GUIDANCE · SAMPLE')}</span><h1 id="meeting-heading" tabindex="-1">${t('Zeit für deine nächsten Schritte.','Time for your next steps.')}</h1>${meetingNotice()}<nav class="portal-nav" aria-label="${t('Beratung und Anliegen','Guidance and enquiries')}">${link(t('Meine Termine','My appointments'),'/portal/appointments','secondary')}${link(t('Anliegen','Support'),'/portal/support','secondary')}${link(t('Nachrichten','Messages'),'/portal/messages','secondary')}</nav>${meetingError()}<section class="learning-panel"><h2>${t('Freigegebene Musterzeitfenster','Released sample slots')}</h2><label class="field">${t('Beratungsthema','Guidance topic')}<select id="meeting-topic">${caseOptions(MEETING_TOPICS,MEETINGS.topic)}</select></label>${slots.length?`<div class="case-list">${slots.map(s=>`<article class="case-message">${meetingContext(s)}<button class="btn secondary" data-meeting-pick="${s.id}">${active?t('Diesen Ersatztermin wählen','Choose this replacement slot'):t('Diesen Mustertermin wählen','Choose this sample slot')}</button></article>`).join('')}</div>`:`<p class="learning-empty">${t('Kein passendes freigegebenes Musterzeitfenster. Nicht freigegebene oder bereits belegte Zeiten werden nicht angeboten.','No matching released sample slot. Unreleased or occupied slots are not offered.')}</p>`}<p>${t('Videotermine bleiben ohne geprüfte technische Anbindung gesperrt. Es wird kein Zoom-/BBB-Link erfunden. Erinnerungsregeln sind noch nicht festgelegt.','Video appointments remain blocked without a verified technical connection. No Zoom/BBB link is invented. Reminder rules have not been defined.')}</p></section><section class="learning-panel"><h2>${t('Deine lokalen Termine','Your local appointments')}</h2>${MEETINGS.bookings.length?`<div class="case-list">${MEETINGS.bookings.map(x=>`<button class="case-card" data-meeting-booking="${x.id}" aria-pressed="${x.id===MEETINGS.bookingSelected}"><b>${x.id} · ${caseLabel(MEETING_TOPICS,x.slot.topic)}</b><span>${esc(x.slot.date)} · ${esc(x.slot.start)} · ${meetingStatus(x)}</span></button>`).join('')}</div>`:`<p>${t('Noch kein Termin lokal vorgemerkt.','No appointment recorded locally yet.')}</p>`}</section>${b&&meetingVisible(b)?`<section class="learning-panel"><h2>${b.id} · ${meetingStatus(b)}</h2>${meetingContext(b.slot)}${b.status==='booked'?`<p>${b.changesAllowed?t('Änderung im Muster ausdrücklich geprüft. Ersatztermin oben wählen oder lokale Vormerkung stornieren.','Change explicitly reviewed in this sample. Choose a replacement slot above or cancel the local record.'):t('Umbuchung und Stornierung noch nicht fachlich geprüft. Die zuständige Beratung muss die Musterprüfung dokumentieren. Es gelten keine erfundenen Stornofristen.','Rescheduling and cancellation have not been reviewed. The responsible adviser must document the sample review. No cancellation deadlines are invented.')}</p>${meetingButton('Lokale Vormerkung stornieren','Cancel local record','cancel')}`:''}${meetingSummary(b)}${meetingHistory(b)}</section>`:''}<div class="actions">${link(t('Beratungskalender · Mitarbeiterdemo','Guidance calendar · staff demo'),'/staff/calendar','secondary')}${link(t('Mein Portal','My portal'),'/portal/student','secondary')}</div><p class="learning-source">WF-W15-07-01/-02 · ${t('Teilweise Frontenddemonstration. Keine verbindliche Terminbestätigung.','Partial frontend demonstration. No binding appointment confirmation.')}</p></div>`}
function meetingStaffPanel(){const owned=MEETINGS.slots.filter(s=>s.owner===CASES.owner),s=meetingSlot(),slotVisible=s&&s.owner===CASES.owner,b=meetingBooking(),bookingVisible=b&&meetingVisible(b),list=MEETINGS.bookings.filter(x=>x.slot.owner===CASES.owner);return `<section class="learning-panel meeting-journey"><h2 id="meeting-heading" tabindex="-1">${t('Beratungsfenster und Gesprächsdokumentation','Guidance slots and conversation records')}</h2>${meetingNotice()}${meetingError()}<p>${t('Dieselbe Musterrolle wie im Fristenkalender. Nur zugeordnete Beratungsfenster und Gespräche. Die drei Fenster sind bearbeitbare Szenariodaten, keine verfügbare Kapazität.','Uses the same sample role as the deadline calendar. Only assigned guidance slots and conversations. The three slots are editable scenario data, not available capacity.')}</p><div class="case-list">${owned.map(x=>`<button class="case-card" data-meeting-slot="${x.id}"><b>${x.id} · ${esc(x.date)} · ${esc(x.start)}</b><span>${x.booking?t('Im Muster belegt','Occupied in sample'):x.published?t('Lokal freigegeben','Released locally'):t('Nicht freigegeben','Not released')}</span></button>`).join('')}</div>${!owned.length?`<p class="learning-empty">${t('Keine Beratungsfenster für diese Musterrolle.','No guidance slots for this sample role.')}</p>`:''}${slotVisible?`<section class="meeting-slot-editor"><h3>${s.id}</h3>${s.published?`${meetingContext(s)}${s.booking?`<p>${t('Belegtes Fenster bleibt unverändert. Änderungen laufen über den dokumentierten Terminweg.','Occupied slots remain unchanged. Use the documented appointment flow for changes.')}</p>`:meetingButton('Freigabe lokal zurücknehmen','Withdraw local release','withdraw')}`:`<div class="case-fields"><label class="field">${t('Thema','Topic')}<select id="meeting-slot-topic">${caseOptions(MEETING_TOPICS,s.topic)}</select></label><label class="field">${t('Fiktives Datum','Fictional date')}<input type="date" id="meeting-slot-date" value="${esc(s.date)}"></label><label class="field">${t('Beginn · Musterzeit','Start · sample time')}<input type="time" id="meeting-slot-start" value="${esc(s.start)}"></label><label class="field">${t('Ende · Musterzeit','End · sample time')}<input type="time" id="meeting-slot-end" value="${esc(s.end)}"></label><label class="field">${t('Format','Format')}<select id="meeting-slot-mode"><option value="onsite" ${s.mode==='onsite'?'selected':''}>${t('Vor Ort · Muster','In person · sample')}</option><option value="video" ${s.mode==='video'?'selected':''}>${t('Video · Anbindung fehlt','Video · connection missing')}</option></select></label><label class="field">${t('Fiktiver Gesprächsort','Fictional meeting place')}<input id="meeting-slot-place" maxlength="200" value="${esc(s.place)}"></label></div><label class="attendance-check"><input id="meeting-slot-checked" type="checkbox" ${s.checked?'checked':''}>${t('Musterzeit, Thema, Zuständigkeit und Ort geprüft','Sample time, topic, assignment and place reviewed')}</label>${meetingButton('Zeitfenster lokal freigeben','Release slot locally','publish')}`}</section>`:''}<h3>${t('Zugeordnete Mustertermine','Assigned sample appointments')}</h3><div class="case-list">${list.map(x=>`<button class="case-card" data-meeting-booking="${x.id}" aria-pressed="${x.id===MEETINGS.bookingSelected}"><b>${x.id} · ${esc(x.slot.date)} · ${esc(x.slot.start)}</b><span>${meetingStatus(x)}</span></button>`).join('')}</div>${!list.length?`<p>${t('Noch keine zugeordneten Termine.','No assigned appointments yet.')}</p>`:''}${bookingVisible?meetingStaffBooking(b):''}<div class="actions">${link(t('Teilnehmer-Terminansicht · Demo','Learner appointments · demo'),'/portal/appointments','secondary')}</div><p class="learning-source">WF-W15-07-01/-02 · ${t('Kein CRM, Videodienst, Versand oder Reminder angebunden.','No CRM, video service, sending or reminders connected.')}</p></section>`}
function meetingStaffBooking(b){const last=b.docs.at(-1);return `<section class="meeting-booking"><h3>${b.id} · ${meetingStatus(b)}</h3>${meetingContext(b.slot)}${b.status==='booked'?`<label class="field">${t('Begründung der Musterprüfung für Terminänderungen','Reason for sample appointment-change review')}<textarea id="meeting-change-reason" maxlength="1500">${esc(b.changeReason)}</textarea></label><label class="attendance-check"><input id="meeting-change-checked" type="checkbox" ${b.changeChecked?'checked':''}>${t('Umbuchung/Stornierung in diesem Musterfall fachlich geprüft und zulässig','Rescheduling/cancellation reviewed and permitted in this sample case')}</label>${meetingButton('Änderungsprüfung lokal dokumentieren','Record change review locally','allow-changes')}<p>${t('Einzelfallprüfung im Muster, keine allgemeine Fristregel. Nach Umbuchung erneut prüfen.','Sample case review, not a general deadline rule. Review again after rescheduling.')}</p>`:''}${b.status!=='cancelled'?`<section class="learning-panel"><h3>${t('Gespräch getrennt dokumentieren','Document the conversation separately')}</h3><label class="field">${t('Interne fiktive Notiz · nicht für das Portal','Internal fictional note · not for the portal')}<textarea id="meeting-note" maxlength="3000">${esc(b.note)}</textarea></label><label class="field">${t('Zusammenfassungsentwurf · nur fiktiv','Summary draft · fictional only')}<textarea id="meeting-summary" maxlength="3000">${esc(b.summary)}</textarea></label><label class="attendance-check"><input id="meeting-occurred" type="checkbox" ${b.occurred?'checked':''}>${t('Das Gespräch hat im Musterszenario stattgefunden','The conversation took place in the sample scenario')}</label><label class="attendance-check"><input id="meeting-doc-checked" type="checkbox" ${b.docChecked?'checked':''}>${t('Entwurf geprüft und notwendige Inhalte getrennt','Draft reviewed and necessary content separated')}</label>${meetingButton('Geprüfte Dokumentation intern übernehmen','Record reviewed documentation internally','document')}<p>${t('Manueller Entwurf, keine KI-Verarbeitung oder Aufzeichnung. Auch geprüfte Dokumentation erscheint erst nach gesonderter Freigabe im Portal.','Manual draft, no AI processing or recording. Even reviewed documentation appears in the portal only after a separate release.')}</p>${last?`<h4>${t('Zuletzt intern geprüfte Fassung','Latest internally reviewed version')} ${last.version}</h4><p class="learning-preserve">${esc(last.summary)}</p><label class="attendance-check"><input id="meeting-portal-checked" type="checkbox" ${b.portalChecked?'checked':''}>${t('Genau diese Zusammenfassung für die Musterperson im Portal geprüft','This exact summary reviewed for the sample learner’s portal')}</label>${meetingButton('Zusammenfassung lokal im Portal freigeben','Release summary locally in portal','release-summary')}<details><summary>${t('Interne Dokumentationsversionen','Internal documentation versions')}</summary>${b.docs.map(d=>`<article class="case-message"><b>${t('Version','Version')} ${d.version} · ${esc(d.at)} · ${caseOwnerLabel(d.author)}</b><p class="learning-preserve">${esc(d.summary)}</p><p><b>${t('Interne Notiz','Internal note')}</b></p><p class="learning-preserve">${esc(d.note)}</p></article>`).join('')}</details>`:''}</section>`:''}${meetingSummary(b)}${b.released.length?`<section class="learning-panel"><h3>${t('Folgeaufgaben im gemeinsamen Vorgang','Follow-up tasks in the shared case')}</h3><p>${t('Es wird nur die ausdrücklich freigegebene Zusammenfassung übernommen. Interne Gesprächsnotizen werden nicht kopiert. Aufgaben, Fristen und Übergaben bleiben im bestehenden Vorgangsmodul.','Only the explicitly released summary is copied. Internal conversation notes are not copied. Tasks, dates and handovers remain in the existing case module.')}</p>${b.caseId?`<p>${esc(b.caseId)} · ${t('Verknüpfter Vorgang; neue Zusammenfassungsversionen nicht automatisch übertragen.','Linked case; new summary versions are not copied automatically.')}</p>${meetingButton('Verknüpften Vorgang öffnen','Open linked case','followup')}`:meetingButton('Beratungsfolge lokal als Vorgang anlegen','Create guidance follow-up case locally','followup')}</section>`:''}${meetingHistory(b,true)}</section>`}
function meetingTimeValid(value){return /^([01]\d|2[0-3]):[0-5]\d$/.test(value)}
function meetingSlotSnapshot(s){return {id:s.id,owner:s.owner,topic:s.topic,date:s.date,start:s.start,end:s.end,mode:s.mode,place:s.place}}
function meetingAction(action,slotId){MEETINGS.error=null;const fail=(de,en)=>{MEETINGS.error=[de,en];MEETINGS.errorRoute=route();render();document.getElementById('meeting-error')?.focus()};const s=meetingSlot(),b=meetingBooking();
 if(action==='publish'&&meetingStaff()&&s&&s.owner===CASES.owner&&!s.published){
  if(s.mode!=='onsite')return fail('Videofenster ohne geprüfte Anbindung nicht freigeben.','Do not release video slots without a verified connection.');
  if(!caseValidDate(s.date)||!meetingTimeValid(s.start)||!meetingTimeValid(s.end)||s.start>=s.end||!Object.hasOwn(MEETING_TOPICS,s.topic)||!s.place.trim()||!s.checked)return fail('Gültige Musterzeiten, Thema, Ort und Prüfbestätigung ergänzen.','Provide valid sample times, topic, place and verification.');
  if(MEETINGS.slots.some(x=>x.id!==s.id&&x.owner===s.owner&&x.published&&x.date===s.date&&x.start<s.end&&s.start<x.end))return fail('Dieses Fenster überschneidet sich mit einer vorhandenen Freigabe der Musterberatung.','This slot overlaps another released slot for the sample adviser.');
  s.place=s.place.trim();s.published=true;
 }else if(action==='withdraw'&&meetingStaff()&&s&&s.owner===CASES.owner&&s.published){if(s.booking)return fail('Belegte Zeitfenster können nicht zurückgenommen werden.','Occupied slots cannot be withdrawn.');s.published=false;s.checked=false;
 }else if(action==='pick'&&meetingOwn()){
  const target=MEETINGS.slots.find(x=>x.id===slotId);if(!target||!target.published||target.booking||target.topic!==MEETINGS.topic)return fail('Dieses Musterfenster ist nicht verfügbar oder passt nicht zum gewählten Thema.','This sample slot is unavailable or does not match the selected topic.');
  const active=MEETINGS.bookings.find(x=>x.status==='booked');
  if(active){if(!active.changesAllowed)return fail('Änderung zuerst durch die zuständige Beratung im Muster prüfen lassen.','Have the responsible adviser review this sample change first.');
   const old=active.slot;MEETINGS.slots.find(x=>x.id===old.id).booking=null;active.slot=meetingSlotSnapshot(target);target.booking=active.id;active.changesAllowed=false;active.changeReason='';active.changeChecked=false;active.note='';active.summary='';active.docChecked=false;active.portalChecked=false;active.occurred=false;MEETINGS.bookingSelected=active.id;meetingEvent(active,['Mustertermin umgebucht; vorheriges Fenster freigegeben.','Sample appointment rescheduled; previous slot released.'],old.date+' '+old.start+' → '+target.date+' '+target.start);
  }else{const id='DEMO-MEETING-'+String(MEETINGS.bookings.length+1).padStart(3,'0'),record={id,slot:meetingSlotSnapshot(target),status:'booked',changesAllowed:false,changeReason:'',changeChecked:false,note:'',summary:'',occurred:false,docChecked:false,portalChecked:false,docs:[],released:[],history:[],caseId:null};MEETINGS.bookings.push(record);target.booking=id;MEETINGS.bookingSelected=id;meetingEvent(record,['Mustertermin lokal vorgemerkt; keine echte Buchung.','Sample appointment recorded locally; no actual booking.']);}
 }else if(action==='cancel'&&meetingOwn()&&b&&b.status==='booked'){
  if(!b.changesAllowed)return fail('Stornierung zuerst durch die zuständige Beratung im Muster prüfen lassen.','Have the responsible adviser review this sample cancellation first.');b.status='cancelled';MEETINGS.slots.find(x=>x.id===b.slot.id).booking=null;b.changesAllowed=false;b.note='';b.summary='';meetingEvent(b,['Lokale Vormerkung storniert; kein gültiger Termin mehr aus dieser Vormerkung.','Local record cancelled; this record no longer represents an active appointment.']);
 }else if(meetingStaff()&&meetingVisible(b)){
  if(action==='allow-changes'&&b.status==='booked'){if(!b.changeChecked||!b.changeReason.trim())return fail('Musterprüfung und Begründung erforderlich.','Sample verification and reason are required.');b.changesAllowed=true;meetingEvent(b,['Terminänderung im Muster geprüft.','Appointment change reviewed in sample.'],b.changeReason.trim(),false);b.changeChecked=false;
  }else if(action==='document'&&b.status!=='cancelled'){
   if(!b.occurred||!b.docChecked||!b.summary.trim())return fail('Stattgefundenes Mustergespräch, Zusammenfassung und Prüfung bestätigen.','Confirm the sample conversation took place, provide a summary and verify it.');
   const last=b.docs.at(-1);if(last&&last.summary===b.summary.trim()&&last.note===b.note.trim())return fail('Diese Dokumentationsfassung ist bereits übernommen.','This documentation version is already recorded.');
   const doc={version:b.docs.length+1,summary:b.summary.trim(),note:b.note.trim(),at:new Date().toISOString(),author:CASES.owner};b.docs.push(doc);b.status='completed';b.changesAllowed=false;b.docChecked=false;b.portalChecked=false;meetingEvent(b,['Gespräch intern dokumentiert; Portalinhalt noch nicht freigegeben.','Conversation documented internally; portal content not yet released.'],'',false);
  }else if(action==='release-summary'&&b.status==='completed'){
   const last=b.docs.at(-1);if(!last||!b.portalChecked)return fail('Geprüfte Dokumentation und gesonderte Portalfreigabe erforderlich.','Reviewed documentation and separate portal approval are required.');
   if(last.summary!==b.summary.trim()||last.note!==b.note.trim())return fail('Der Entwurf wurde geändert. Zuerst erneut intern prüfen und übernehmen.','The draft has changed. Review and record it internally again first.');
   if(b.released.some(x=>x.version===last.version))return fail('Diese Fassung ist bereits freigegeben.','This version is already released.');
   b.released.push({version:last.version,summary:last.summary,at:new Date().toISOString(),author:CASES.owner});b.portalChecked=false;meetingEvent(b,['Geprüfte Zusammenfassung ausdrücklich lokal im Portal freigegeben.','Reviewed summary explicitly released locally in the portal.']);
  }else if(action==='followup'&&b.released.length){
   if(b.caseId){const linked=CASES.records.find(x=>x.id===b.caseId);if(!linked||linked.owner!==CASES.owner)return fail('Verknüpfter Vorgang liegt bei einer anderen Musterzuständigkeit. Dort prüfen; keinen zweiten Vorgang erzeugen.','The linked case belongs to another sample owner. Review it there; do not create a duplicate.');CASES.selected=b.caseId;location.hash='#/staff/cases';return;}
   const released=b.released.at(-1),now=new Date().toISOString(),id='DEMO-CASE-'+String(CASES.records.length+1).padStart(3,'0');
   CASES.records.push({id,subject:b.id,category:'admin',owner:CASES.owner,status:'working',created:now,messages:[{actor:CASES.owner,text:released.summary,at:now}],history:[{at:now,actor:CASES.owner,label:['Beratungsfolge aus freigegebener Zusammenfassung angelegt.','Guidance follow-up created from released summary.'],text:b.id+' · '+t('Version','Version')+' '+released.version,public:true}],tasks:[],reply:'',staffReply:'',note:'',transfer:CASES.owner,taskDraft:{title:'',owner:CASES.owner,priority:'normal',due:'',follow:'',verified:false}});b.caseId=id;CASES.selected=id;meetingEvent(b,['Gemeinsamen Folge-Vorgang angelegt.','Shared follow-up case created.'],id);location.hash='#/staff/cases';return;
  }else return;
 }else return;
 render();document.getElementById('meeting-heading')?.focus();
}
const meetingBodyBefore=v3Body;v3Body=function(r){if(MEETING_ROUTES.includes(r))return meetingStudent();return meetingBodyBefore(r)};
const meetingTasksBefore=caseTasks;caseTasks=function(calendar=false){const html=meetingTasksBefore(calendar);return calendar?html.replace(t('Fristen aus dem führenden Vorgang.','Dates from the source case.'),t('Beratung und Fristen. Ein Kalender.','Guidance and deadlines. One calendar.')).replace('<section class="learning-panel">',meetingStaffPanel()+'<section class="learning-panel">'):html};
const meetingGuidanceBefore=v3Guidance;v3Guidance=function(a){if(meetingOwn())return [t('Nur freigegebene Musterzeiten.','Released sample times only.'),t('Terminänderungen werden geprüft. Gesprächsnotizen bleiben intern, bis eine Zusammenfassung ausdrücklich freigegeben wird.','Appointment changes require review. Conversation notes remain internal until a summary is explicitly released.'),[['Meine Termine','My appointments','/portal/appointments'],['Anliegen','Support','/portal/support']]];return meetingGuidanceBefore(a)};
const meetingPortalBefore=portalContent;portalContent=function(role,view){return meetingPortalBefore(role,view)+(['student','applicant'].includes(role)&&view==='overview'?`<section class="learning-panel"><h2>${t('Deine Beratungstermine','Your guidance appointments')}</h2>${link(t('Mustertermine verwalten','Manage sample appointments'),'/portal/appointments','secondary')}</section>`:'')};
const meetingCaseShellBefore=caseShell;caseShell=function(title,body){const html=meetingCaseShellBefore(title,body);return caseOwn()?html.replace('</nav>',`<a href="#/portal/appointments">${t('Meine Termine','My appointments')}</a></nav>`):html};
const meetingBindBefore=v3Bind;v3Bind=function(){meetingBindBefore();if(!meetingOwn()&&!meetingStaff())return;const refresh=()=>{MEETINGS.error=null;render();document.getElementById('meeting-heading')?.focus()};
 document.querySelectorAll('[data-meeting-action]').forEach(e=>e.addEventListener('click',()=>meetingAction(e.dataset.meetingAction)));
 document.querySelectorAll('[data-meeting-pick]').forEach(e=>e.addEventListener('click',()=>meetingAction('pick',e.dataset.meetingPick)));
 document.querySelectorAll('[data-meeting-slot]').forEach(e=>e.addEventListener('click',()=>{const s=MEETINGS.slots.find(x=>x.id===e.dataset.meetingSlot);if(!s||!meetingStaff()||s.owner!==CASES.owner)return;MEETINGS.slotSelected=s.id;refresh()}));
 document.querySelectorAll('[data-meeting-booking]').forEach(e=>e.addEventListener('click',()=>{const b=MEETINGS.bookings.find(x=>x.id===e.dataset.meetingBooking);if(!meetingVisible(b))return;MEETINGS.bookingSelected=b.id;refresh()}));
 document.getElementById('meeting-topic')?.addEventListener('change',e=>{if(!Object.hasOwn(MEETING_TOPICS,e.target.value))return;MEETINGS.topic=e.target.value;refresh()});
 for(const key of ['topic','date','start','end','mode','place','checked'])document.getElementById('meeting-slot-'+key)?.addEventListener(['topic','mode','checked'].includes(key)?'change':'input',e=>{const s=meetingSlot();if(!s||s.owner!==CASES.owner||s.published)return;s[key]=key==='checked'?e.target.checked:e.target.value;if(key!=='checked'){s.checked=false;const box=document.getElementById('meeting-slot-checked');if(box)box.checked=false}});
 for(const [id,key,check]of [['change-reason','changeReason'],['change-checked','changeChecked',true],['note','note'],['summary','summary'],['occurred','occurred',true],['doc-checked','docChecked',true],['portal-checked','portalChecked',true]])document.getElementById('meeting-'+id)?.addEventListener(check?'change':'input',e=>{const b=meetingBooking();if(!meetingStaff()||!meetingVisible(b))return;b[key]=check?e.target.checked:e.target.value;if(['note','summary'].includes(key)){b.docChecked=false;b.portalChecked=false;for(const id of ['meeting-doc-checked','meeting-portal-checked']){const box=document.getElementById(id);if(box)box.checked=false}}});
};
render();
